<?php
declare(strict_types=1);
$cid=$user['company_id'];$selectedProject=(string)($_GET['project']??($projects[0]['id']??''));if($selectedProject&&!scoped_project($db,$user,$selectedProject))$selectedProject=(string)($projects[0]['id']??'');
$pname='All projects';foreach($projects as $p)if($p['id']===$selectedProject)$pname=$p['name'];
$materials=phase_rows($db,'SELECT m.*,m.opening_stock+COALESCE(SUM(CASE WHEN t.transaction_type IN("received","returned","adjustment") THEN t.quantity WHEN t.transaction_type IN("issued","wasted","transferred") THEN -t.quantity ELSE 0 END),0) current_stock FROM materials m LEFT JOIN material_transactions t ON t.material_id=m.id WHERE m.company_id=? AND m.project_id=? GROUP BY m.id ORDER BY m.name',[$cid,$selectedProject]);
$vendors=phase_rows($db,'SELECT * FROM vendors WHERE company_id=? ORDER BY created_at DESC',[$cid]);
$workers=phase_rows($db,'SELECT l.*,COALESCE(SUM(a.daily_cost),0) month_cost,COUNT(CASE WHEN a.attendance_status="present" THEN 1 END) days_present FROM labour l LEFT JOIN labour_attendance a ON a.labour_id=l.id AND a.attendance_date>=DATE_FORMAT(CURDATE(),"%Y-%m-01") WHERE l.company_id=? AND l.project_id=? GROUP BY l.id ORDER BY l.name',[$cid,$selectedProject]);
$requests=phase_rows($db,'SELECT pr.*,m.name material_name,u.name requester FROM purchase_requests pr LEFT JOIN materials m ON m.id=pr.material_id LEFT JOIN users u ON u.id=pr.requested_by WHERE pr.company_id=? AND pr.project_id=? ORDER BY pr.created_at DESC',[$cid,$selectedProject]);
$orders=phase_rows($db,'SELECT po.*,v.name vendor_name FROM purchase_orders po JOIN vendors v ON v.id=po.vendor_id WHERE po.company_id=? AND po.project_id=? ORDER BY po.created_at DESC',[$cid,$selectedProject]);
$progressRows=phase_rows($db,'SELECT * FROM site_progress WHERE company_id=? AND project_id=? ORDER BY created_at DESC',[$cid,$selectedProject]);
$expenses=phase_rows($db,'SELECT e.*,v.name vendor_name FROM expenses e LEFT JOIN vendors v ON v.id=e.vendor_id WHERE e.company_id=? AND e.project_id=? ORDER BY expense_date DESC',[$cid,$selectedProject]);
$leads=phase_rows($db,'SELECT l.*,p.name project_name,u.name assigned_name FROM leads l LEFT JOIN projects p ON p.id=l.project_id LEFT JOIN users u ON u.id=l.assigned_to WHERE l.company_id=? ORDER BY l.updated_at DESC LIMIT 200',[$cid]);
$followups=phase_rows($db,'SELECT f.*,l.name lead_name,u.name assigned_name FROM followups f JOIN leads l ON l.id=f.lead_id JOIN users u ON u.id=f.assigned_user_id WHERE f.company_id=? ORDER BY f.followup_at',[$cid]);
$visits=phase_rows($db,'SELECT v.*,l.name lead_name,p.name project_name,u.name assigned_name FROM site_visits v JOIN leads l ON l.id=v.lead_id JOIN projects p ON p.id=v.project_id JOIN users u ON u.id=v.assigned_user_id WHERE v.company_id=? ORDER BY v.visit_at DESC',[$cid]);
$emails=phase_rows($db,'SELECT q.*,l.name lead_name FROM email_queue q JOIN leads l ON l.id=q.lead_id WHERE q.company_id=? ORDER BY q.created_at DESC LIMIT 100',[$cid]);
$construction=phase_one($db,'SELECT (SELECT COALESCE(SUM(amount+tax),0) FROM expenses WHERE company_id=? AND project_id=? AND status IN("approved","paid")) spent,(SELECT COALESCE(SUM(daily_cost),0) FROM labour_attendance WHERE company_id=? AND project_id=? AND attendance_date=CURDATE()) labour_today,(SELECT COUNT(*) FROM labour_attendance WHERE company_id=? AND project_id=? AND attendance_date=CURDATE() AND attendance_status IN("present","half_day")) workers_today,(SELECT COALESCE(AVG(progress),0) FROM site_progress WHERE company_id=? AND project_id=?) site_progress',[$cid,$selectedProject,$cid,$selectedProject,$cid,$selectedProject,$cid,$selectedProject]);
?>
<section class="page-title"><div><span class="eyebrow"><?=e(strtoupper($pname))?></span><h1><?=e(match($page){'construction'=>'Project dashboard','materials'=>'Materials & stock','labour'=>'Labour & attendance','purchases'=>'Purchase management','vendors'=>'Vendor management','expenses'=>'Finance & expenses','progress'=>'Site progress','leads'=>'Sales leads','followups'=>'Follow-ups','visits'=>'Site visits','emails'=>'Email queue',default=>'Operations'})?></h1><p class="muted">Live operational records connected to your company and selected project.</p></div><form method="get" class="project-filter"><input type="hidden" name="business" value="construction"><input type="hidden" name="page" value="<?=e($page)?>"><select name="project" data-auto-submit><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=$p['id']===$selectedProject?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form></section>
