<?php elseif($page==='materials'):?>
<div class="split"><form class="form-card" method="post"><h2>Add material</h2><?=phase_hidden('material_add','materials',$selectedProject)?><label class="field">Material name<input name="name" required></label><div class="form-grid"><label class="field">Category<input name="category" required></label><label class="field">Unit<input name="unit" placeholder="bags, kg, pcs" required></label></div><div class="form-grid"><label class="field">Opening stock<input type="number" step=".001" name="opening_stock"></label><label class="field">Minimum required stock<input type="number" step=".001" name="minimum_stock"></label></div><label class="field">Storage location<input name="storage_location"></label><label class="field">Supplier<input name="supplier"></label><button class="button">Save material</button></form><form class="form-card" method="post"><h2>Record stock activity</h2><?=phase_hidden('material_tx','materials',$selectedProject)?><label class="field">Material<select name="material_id"><?php foreach($materials as $m):?><option value="<?=e($m['id'])?>"><?=e($m['name'])?></option><?php endforeach;?></select></label><label class="field">Activity<select name="transaction_type"><option value="received">Material received</option><option value="issued">Material used</option><option value="returned">Material returned</option><option value="wasted">Material wasted</option><option value="adjustment">Stock adjustment</option></select></label><div class="form-grid"><label class="field">Quantity<input type="number" step=".001" name="quantity" required></label><label class="field">Rate<input type="number" step=".01" name="rate"></label></div><label class="field">Date<input type="date" name="transaction_date" value="<?=date('Y-m-d')?>"></label><label class="field">Notes<input name="notes"></label><button class="button">Save Activity</button></form></div><?=phase_table(['Material','Category','Opening','Balance','Minimum','Status'],array_map(fn($m)=>[e($m['name']),e($m['category']),e($m['opening_stock'].' '.$m['unit']),e($m['current_stock'].' '.$m['unit']),e($m['minimum_stock'].' '.$m['unit']),(float)$m['current_stock']<=(float)$m['minimum_stock']?'<span class="pill bad">Low stock</span>':'<span class="pill good">Available</span>'],$materials))?>
<?php elseif($page==='vendors'):?>
<form class="form-card wide" method="post"><h2>Add vendor</h2><?=phase_hidden('vendor_add','vendors',$selectedProject)?><div class="form-grid"><label class="field">Contact name<input name="name" required></label><label class="field">Company<input name="company_name"></label><label class="field">Category<input name="category"></label><label class="field">Phone<input name="phone"></label><label class="field">Email<input type="email" name="email"></label><label class="field">GST<input name="gst"></label></div><label class="field">Payment terms<input name="payment_terms"></label><button class="button">Save vendor</button></form><?=phase_table(['Vendor','Company','Contact','Category','Terms','Status'],array_map(fn($v)=>[e($v['name']),e($v['company_name']),e($v['phone']).'<small>'.e($v['email']).'</small>',e($v['category']),e($v['payment_terms']),'<span class="pill good">'.e($v['status']).'</span>'],$vendors))?>
