n" name="record_id" value="'.e($r['id']).'"><button class="text-button" name="status" value="approved">Approve</button> <button class="text-button danger" name="status" value="rejected">Reject</button></form>':'';return[e($r['material_name']?:'General'),e($r['quantity']),e($r['required_date']),e($r['priority']),'<span class="pill">'.e($r['status']).'</span>',$actions];},$requests))?><?=phase_table(['PO','Vendor','Amount','Delivery','Status'],array_map(fn($o)=>[e($o['po_number']),e($o['vendor_name']),inr($o['amount']),e($o['expected_delivery']),'<span class="pill">'.e($o['status']).'</span>'],$orders))?>
