<form class="form-card wide" method="post"><h2>Schedule site visit</h2><?=phase_hidden('visit_add','visits',$selectedProject)?><div class="form-grid"><label class="field">Lead<select name="lead_id"><?php foreach($leads as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'])?></option><?php endforeach;?></select></label><label class="field">Project<select name="project_id"><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label class="field">Executive<select name="assigned_user_id"><?php foreach($users as $u):?><option value="<?=e($u['id'])?>"><?=e($u['name'])?></option><?php endforeach;?></select></label><label class="field">Date & time<input type="datetime-local" name="visit_at" required></label><label class="field">Guests<input type="number" min="1" name="guests" value="1"></label><label class="field">Unit interested<input name="unit_interested"></label><label class="field">Budget<input type="number" name="budget"></label><label class="field">Status<select name="status"><?php foreach(['scheduled','completed','cancelled','no_show','rescheduled'] as $x):?><option value="<?=$x?>"><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach;?></select></label></div><label class="field">Notes<input name="notes"></label><button class="button">Schedule visit</button></form><?=phase_table(['When','Lead','Project','Executive','Unit','Status'],array_map(fn($v)=>[e(date('d M Y, h:i A',strtotime($v['visit_at']))),e($v['lead_name']),e($v['project_name']),e($v['assigned_name']),e($v['unit_interested']),'<span class="pill">'.e(str_replace('_',' ',$v['status'])).'</span>'],$visits))?>
<?php else:?>
<form class="form-card wide" method="post"><h2>Queue individual email</h2><p class="muted">Messages are stored safely for a future SMTP/SES/SendGrid provider. No email is falsely marked as sent.</p><?=phase_hidden('email_queue','emails',$selectedProject)?><label class="field">Lead<select name="lead_id"><?php foreach($leads as $l):?><option value="<?=e($l['id'])?>"><?=e($l['name'].' · '.$l['email'])?></option><?php endforeach;?></select></label><label class="field">Subject<input name="subject" required></label><label class="field">Message<textarea name="body" rows="7" required></textarea></label><button class="button">Add to email queue</button></form><?=phase_table(['Lead','Recipient','Subject','Created','Status'],array_map(fn($q)=>[e($q['lead_name']),e($q['recipient']),e($q['subject']),e($q['created_at']),'<span class="pill">'.e($q['status']).'</span>'],$emails))?>
<?php endif;?>
